#' Estimate Improvement in R-Squared
#' and Generate the Corresponding Sampling Distribution
#' Using the Monte Carlo Method
#'
#' @author Ivan Jacob Agaloos Pesigan
#'
#' @details The vector of improvement in R-squared
#'   (\eqn{\Delta R^{2}})
#'   is derived from each randomly generated vector of parameter estimates.
#'   Confidence intervals are generated by obtaining
#'   percentiles corresponding to \eqn{100(1 - \alpha)\%}
#'   from the generated sampling
#'   distribution of \eqn{\Delta R^{2}},
#'   where \eqn{\alpha} is the significance level.
#'
#' @return Returns an object
#'   of class `betamc` which is a list with the following elements:
#'   \describe{
#'     \item{call}{Function call.}
#'     \item{args}{Function arguments.}
#'     \item{thetahatstar}{Sampling distribution of
#'       \eqn{\Delta R^{2}}.}
#'     \item{vcov}{Sampling variance-covariance matrix of
#'       \eqn{\Delta R^{2}}.}
#'     \item{est}{Vector of estimated
#'       \eqn{\Delta R^{2}}.}
#'     \item{fun}{Function used ("DeltaRSqMC").}
#'   }
#'
#' @inheritParams BetaMC
#'
#' @references
#' Algina, J., Keselman, H. J., & Penfield, R. D. (2007).
#' Confidence intervals for an effect size measure
#' in multiple linear regression.
#' *Educational and Psychological Measurement*, *67*(2), 207--218.
#' \doi{10.1177/0013164406292030}
#'
#' Algina, J., Keselman, H. J., & Penfield, R. D. (2008a).
#' Confidence intervals for the squared multiple semipartial
#' correlation coefficient.
#' *Journal of Modern Applied Statistical Methods*, *7*(1), 2--10.
#' \doi{10.22237/jmasm/1209614460}
#'
#' Algina, J., Keselman, H. J., & Penfield, R. D. (2008b).
#' Note on a confidence interval for the squared semipartial
#' correlation coefficient.
#' *Educational and Psychological Measurement*, *68*(5), 734--741.
#' \doi{10.1177/0013164407313371}
#'
#' Algina, J., Keselman, H. J., & Penfield, R. D. (2010).
#' Confidence intervals for squared semipartial correlation coefficients:
#' The effect of nonnormality.
#' *Educational and Psychological Measurement*, *70*(6), 926--940.
#' \doi{10.1177/0013164410379335}
#'
#' @examples
#' # Data ---------------------------------------------------------------------
#' data("nas1982", package = "betaMC")
#'
#' # Fit Model in lm ----------------------------------------------------------
#' object <- stats::lm(
#'   formula = QUALITY ~ NARTIC + PCTGRT + PCTSUPP,
#'   data = nas1982
#' )
#'
#' # MC -----------------------------------------------------------------------
#' mc <- MC(
#'   object = object,
#'   R = 100, # use a large value e.g., 20000L for actual research
#'   seed = 0508
#' )
#'
#' # DeltaRSqMC ---------------------------------------------------------------
#' out <- DeltaRSqMC(object = mc, alpha = 0.05)
#'
#' ## Methods -----------------------------------------------------------------
#' print(x = out)
#' summary(object = out)
#' coef(object = out)
#' vcov(object = out)
#' confint(object = out, level = 0.95)
#'
#' @family Beta Monte Carlo Functions
#' @keywords betaMC deltarsq
#' @export
DeltaRSqMC <- function(object,
                       alpha = c(0.05, 0.01, 0.001)) {
  sr <- SCorMC(object = object)
  out <- list(
    call = match.call(),
    args = list(
      object = object,
      alpha = alpha
    ),
    thetahatstar = (sr$thetahatstar)^2,
    est = (sr$est)^2,
    fun = "DeltaRSqMC"
  )
  class(x = out) <- c(
    "betamc",
    class(x = out)
  )
  out
}
